"use client"

import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Badge } from "@/components/ui/badge"
import { ConfirmDialog } from "@/components/ui/confirm-dialog"
import { EditModal } from "@/components/ui/edit-modal"

interface Contact {
  id: number
  email: string
  name: string
  topic: string
  created_at: string
}

export default function Contacts() {
  const [contacts, setContacts] = useState<Contact[]>([])
  const [loading, setLoading] = useState(true)
  const [showImportForm, setShowImportForm] = useState(true)
  const [importData, setImportData] = useState("")
  const [newContact, setNewContact] = useState({ email: "", name: "", topic: "" })
  const [editingContact, setEditingContact] = useState<Contact | null>(null)
  const [editModalOpen, setEditModalOpen] = useState(false)
  const [deleteConfirm, setDeleteConfirm] = useState<{ open: boolean; contact: Contact | null }>({ open: false, contact: null })
  const router = useRouter()

  useEffect(() => {
    loadContacts()
  }, [])

  const loadContacts = async () => {
    try {
      const token = localStorage.getItem("auth_token")
      
      if (!token) {
        router.push("/")
        return
      }

      const response = await fetch("/api/contacts", {
        headers: { "Authorization": `Bearer ${token}` }
      })
      
      if (response.ok) {
        const data = await response.json()
        setContacts(data.contacts || [])
      }
    } catch (error) {
      console.error("Error loading contacts:", error)
    } finally {
      setLoading(false)
    }
  }

  const handleCreateContact = async (e: React.FormEvent) => {
    e.preventDefault()
    
    try {
      const token = localStorage.getItem("auth_token")
      const response = await fetch("/api/contacts", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: JSON.stringify(newContact)
      })

      if (response.ok) {
        setNewContact({ email: "", name: "", topic: "" })
        loadContacts()
      }
    } catch (error) {
      console.error("Error creating contact:", error)
    }
  }

  const openEditModal = (contact: Contact) => {
    setEditingContact(contact)
    setEditModalOpen(true)
  }

  const handleEditContact = async (updatedData: { name: string; topic: string }) => {
    if (!editingContact) return
    
    try {
      const token = localStorage.getItem("auth_token")
      const response = await fetch(`/api/contacts/${editingContact.id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: JSON.stringify(updatedData)
      })

      if (response.ok) {
        loadContacts()
        setEditModalOpen(false)
        setEditingContact(null)
      }
    } catch (error) {
      console.error("Error updating contact:", error)
    }
  }

  const handleDeleteContact = async (contactId: number) => {
    try {
      const token = localStorage.getItem("auth_token")
      const response = await fetch(`/api/contacts/${contactId}`, {
        method: "DELETE",
        headers: {
          "Authorization": `Bearer ${token}`
        }
      })

      if (response.ok) {
        loadContacts()
      }
    } catch (error) {
      console.error("Error deleting contact:", error)
    }
  }

  const confirmDeleteContact = (contact: Contact) => {
    setDeleteConfirm({ open: true, contact })
  }

  const handleImportContacts = async (e: React.FormEvent) => {
    e.preventDefault()
    
    try {
      const token = localStorage.getItem("auth_token")
      const response = await fetch("/api/contacts/import-csv", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: JSON.stringify({ file_content: importData })
      })

      if (response.ok) {
        setImportData("")
        setShowImportForm(false)
        loadContacts()
      }
    } catch (error) {
      console.error("Error importing contacts:", error)
    }
  }

  const handleExportContacts = async () => {
    try {
      const token = localStorage.getItem("auth_token")
      const response = await fetch("/api/contacts/export", {
        headers: { "Authorization": `Bearer ${token}` }
      })

      if (response.ok) {
        const data = await response.json()
        const blob = new Blob([data.csv_content], { type: 'text/csv' })
        const url = window.URL.createObjectURL(blob)
        const a = document.createElement('a')
        a.href = url
        a.download = data.filename
        a.click()
        window.URL.revokeObjectURL(url)
      }
    } catch (error) {
      console.error("Error exporting contacts:", error)
    }
  }


  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Cargando contactos...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white shadow-sm border-b">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center space-x-4">
              <Button variant="ghost" onClick={() => router.push("/dashboard")}>
                ← Dashboard
              </Button>
              <h1 className="text-2xl font-bold text-gray-900">Contactos</h1>
            </div>
            <div className="flex space-x-2">
              <Button variant="outline" onClick={handleExportContacts}>
                Exportar CSV
              </Button>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto py-8 px-4 sm:px-6 lg:px-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Add Contact Form */}
          <Card>
            <CardHeader>
              <CardTitle>Agregar Contacto</CardTitle>
              <CardDescription>
                Añade un nuevo contacto manualmente
              </CardDescription>
            </CardHeader>
            <CardContent>
              <form onSubmit={handleCreateContact} className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="email">Email *</Label>
                  <Input
                    id="email"
                    type="email"
                    placeholder="contacto@ejemplo.com"
                    value={newContact.email}
                    onChange={(e) => setNewContact({ ...newContact, email: e.target.value })}
                    required
                  />
                </div>
                
                <div className="space-y-2">
                  <Label htmlFor="name">Nombre</Label>
                  <Input
                    id="name"
                    type="text"
                    placeholder="Nombre del contacto"
                    value={newContact.name}
                    onChange={(e) => setNewContact({ ...newContact, name: e.target.value })}
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="topic">Tema de Interés</Label>
                  <Input
                    id="topic"
                    type="text"
                    placeholder="Ej: Pole Sport, Exotic"
                    value={newContact.topic}
                    onChange={(e) => setNewContact({ ...newContact, topic: e.target.value })}
                  />
                </div>

                <Button type="submit" className="w-full">
                  Agregar Contacto
                </Button>
              </form>
            </CardContent>
          </Card>

          {/* Import CSV Form */}
          {showImportForm && (
            <Card>
              <CardHeader>
                <CardTitle>Importar CSV</CardTitle>
                <CardDescription>
                  Pega el contenido CSV con columnas: email,name,topic
                </CardDescription>
              </CardHeader>
              <CardContent>
                <form onSubmit={handleImportContacts} className="space-y-4">
                  <div className="space-y-2">
                    <Label htmlFor="csv">Contenido CSV</Label>
                    <textarea
                      id="csv"
                      className="w-full h-32 p-3 border border-gray-300 rounded-md resize-none"
                      placeholder="email,name,topic&#10;juan@ejemplo.com,Juan Pérez,Pole Sport&#10;maria@ejemplo.com,Maria García,Exotic"
                      value={importData}
                      onChange={(e) => setImportData(e.target.value)}
                    />
                  </div>

                  <div className="flex space-x-2">
                    <Button type="submit" className="flex-1">
                      Importar
                    </Button>
                    <Button 
                      type="button" 
                      variant="outline" 
                      onClick={() => setImportData("")}
                    >
                      Limpiar
                    </Button>
                  </div>
                </form>
              </CardContent>
            </Card>
          )}

          {/* Contacts List */}
          <div className="lg:col-span-2">
            <Card>
              <CardHeader>
                <CardTitle>Lista de Contactos ({contacts.length})</CardTitle>
                <CardDescription>
                  Gestiona todos tus contactos
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {contacts.length === 0 ? (
                    <p className="text-gray-500 text-center py-8">
                      No hay contactos registrados
                    </p>
                  ) : (
                    contacts.map((contact) => (
                      <div key={contact.id} className="flex items-center justify-between p-4 border rounded-lg">
                        <div className="flex-1">
                          <div className="flex items-center space-x-3">
                            <h3 className="font-medium">{contact.email}</h3>
                            <Badge className={getStatusColor(contact.status)}>
                              {contact.status}
                            </Badge>
                          </div>
                          {contact.name && (
                            <p className="text-sm text-gray-600">{contact.name}</p>
                          )}
                          {contact.topic && (
                            <p className="text-sm text-gray-500">Tema: {contact.topic}</p>
                          )}
                          <p className="text-xs text-gray-400">
                            Creado: {new Date(contact.created_at).toLocaleDateString()}
                          </p>
                        </div>
                        <div className="flex space-x-2">
                          <Button 
                            variant="outline" 
                            size="sm"
                            onClick={() => openEditModal(contact)}
                          >
                            Editar
                          </Button>
                          <Button 
                            variant="outline" 
                            size="sm"
                            onClick={() => confirmDeleteContact(contact)}
                          >
                            Eliminar
                          </Button>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </CardContent>
            </Card>
          </div>
        </div>
      </main>

      {/* Edit Modal */}
      <EditModal
        open={editModalOpen}
        onOpenChange={setEditModalOpen}
        title="Editar Contacto"
        description="Modifica los datos del contacto"
        onSave={() => {
          if (editingContact) {
            handleEditContact({
              name: editingContact.name,
              topic: editingContact.topic
            })
          }
        }}
        onCancel={() => {
          setEditingContact(null)
        }}
      >
        {editingContact && (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="edit_email">Email</Label>
              <Input
                id="edit_email"
                type="email"
                value={editingContact.email}
                disabled
                className="bg-gray-100"
              />
              <p className="text-xs text-gray-500">
                El email no se puede cambiar
              </p>
            </div>

            <div className="space-y-2">
              <Label htmlFor="edit_name">Nombre</Label>
              <Input
                id="edit_name"
                type="text"
                placeholder="Nombre del contacto"
                value={editingContact.name}
                onChange={(e) => setEditingContact({ ...editingContact, name: e.target.value })}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="edit_topic">Tema de Interés</Label>
              <Input
                id="edit_topic"
                type="text"
                placeholder="Ej: Pole Sport, Exotic"
                value={editingContact.topic}
                onChange={(e) => setEditingContact({ ...editingContact, topic: e.target.value })}
              />
            </div>
          </div>
        )}
      </EditModal>

      {/* Delete Confirmation Modal */}
      <ConfirmDialog
        open={deleteConfirm.open}
        onOpenChange={(open) => setDeleteConfirm({ open, contact: null })}
        title="Eliminar Contacto"
        description={`¿Estás seguro de que quieres eliminar el contacto "${deleteConfirm.contact?.name || deleteConfirm.contact?.email}"? Esta acción no se puede deshacer.`}
        confirmText="Eliminar"
        cancelText="Cancelar"
        variant="destructive"
        onConfirm={() => deleteConfirm.contact && handleDeleteContact(deleteConfirm.contact.id)}
      />
    </div>
  )
}
